select public.app_checkout_gateway((:'guestorder'::jsonb->>'id')::uuid,'checkout-demo-02','https://example.test/guest');
select pg_temp.assert((public.app_process_payment(jsonb_build_object('id','event-paid-demo-02','type','paid','order_id',:'guestorder'::jsonb->>'id','gateway_id','checkout-demo-02','amount_cents',12345,'method','PIX'))->>'invite_pending')::boolean,'paid guest invitation pending');
select pg_temp.assert(not (public.app_finalize_paid_order((:'guestorder'::jsonb->>'id')::uuid)->>'finalized')::boolean,'guest no account no entitlement');
select pg_temp.assert(not (public.app_process_payment(jsonb_build_object('id','event-paid-demo-02','type','paid','order_id',:'guestorder'::jsonb->>'id','gateway_id','checkout-demo-02','amount_cents',12345,'method','PIX'))->>'invite_pending')::boolean,'duplicate does not resend invitation');
select pg_temp.assert((public.app_payment_outbox((:'guestorder'::jsonb->>'id')::uuid)->>'invite_pending')::boolean,'outbox recoverable explicitly');
select pg_temp.denied($q$select public.app_local_demo('{}')$q$,'local demo marker denied by default');
reset role;
-- Private uploads: exact reserved path, session, ownership, metadata and ready gate.
select pg_temp.login(1);
set local role authenticated;
select public.app_touch_session(false);
reset role;
set local role service_role;
select pg_temp.service_headers(1);
select public.app_upload_access(pg_temp.uid(1),'ticket-attachment',(:'ticket'::jsonb->>'id')::uuid,'demonstracao.txt','text/plain',20) as upload \gset
select pg_temp.assert(public.app_upload_context(pg_temp.uid(1),(:'upload'::jsonb->>'id')::uuid)->>'status'='pending','upload reserved pending');
select pg_temp.denied(format('select public.app_upload_finalize(%L,%L)',pg_temp.uid(1),:'upload'::jsonb->>'id'),'finalize before object denied');
select pg_temp.denied(format('select public.app_media_access(%L,%L,%L)',pg_temp.uid(1),'ticket-attachment',:'upload'::jsonb->>'id'),'pending upload cannot read');
select pg_temp.service_headers(2);
select pg_temp.denied(format('select public.app_upload_context(%L,%L)',pg_temp.uid(2),:'upload'::jsonb->>'id'),'B cannot get A upload path');
select pg_temp.service_headers(1);
select pg_temp.denied($q$select public.app_upload_access(pg_temp.uid(1),'avatar',pg_temp.uid(2),'a.png','image/png',20)$q$,'cannot reserve another avatar');
select pg_temp.denied($q$select public.app_upload_access(pg_temp.uid(1),'avatar',pg_temp.uid(1),'a.svg','image/svg+xml',20)$q$,'active SVG denied');
reset role;
select pg_temp.login(2);
set local role authenticated;
select pg_temp.denied(format('insert into storage.objects(bucket_id,name,metadata) values(%L,%L,%L::jsonb)','icarus-private',:'upload'::jsonb->>'path','{"size":20,"mimetype":"text/plain"}'),'B cannot upload A reserved path');
select pg_temp.denied($q$insert into storage.objects(bucket_id,name,metadata) values('icarus-private','arbitrary.txt','{}')$q$,'arbitrary storage path denied');
reset role;
select pg_temp.login(1);
set local role authenticated;
insert into storage.objects(bucket_id,name,metadata) values('icarus-private',:'upload'::jsonb->>'path','{"size":19,"mimetype":"text/plain"}');
select pg_temp.assert(not exists(select 1 from storage.objects where bucket_id='icarus-private'),'Storage SELECT denied even after reserved INSERT');
reset role;
set local role service_role;
select pg_temp.service_headers(1);
select pg_temp.denied(format('select public.app_upload_finalize(%L,%L)',pg_temp.uid(1),:'upload'::jsonb->>'id'),'actual size mismatch denied');
reset role;
update storage.objects set metadata='{"size":20,"mimetype":"text/plain"}' where bucket_id='icarus-private' and name=:'upload'::jsonb->>'path';
set local role service_role;
select pg_temp.service_headers(1);
select pg_temp.assert(public.app_upload_finalize(pg_temp.uid(1),(:'upload'::jsonb->>'id')::uuid)->>'state'='ready','valid metadata finalized');
select pg_temp.assert(public.app_media_access(pg_temp.uid(1),'ticket-attachment',(:'upload'::jsonb->>'id')::uuid)->>'storage_path'=:'upload'::jsonb->>'path','ready attachment read authorized');
select pg_temp.denied(format('select public.app_upload_cancel(%L,%L)',pg_temp.uid(1),:'upload'::jsonb->>'id'),'cancel cannot delete ready file');
select public.app_upload_access(pg_temp.uid(1),'avatar',pg_temp.uid(1),'demo.png','image/png',20) as avatar \gset
reset role;
update public.profiles set suspended=true where id=pg_temp.uid(1);
set local role service_role;
select pg_temp.denied(format('select public.app_upload_context(%L,%L)',pg_temp.uid(1),:'avatar'::jsonb->>'id'),'suspended blocks before path return');
reset role;
update public.profiles set suspended=false where id=pg_temp.uid(1);
update public.uploads set expires_at=now()-interval '1 second' where id=(:'avatar'::jsonb->>'id')::uuid;
set local role service_role;
select pg_temp.denied(format('select public.app_upload_context(%L,%L)',pg_temp.uid(1),:'avatar'::jsonb->>'id'),'expired upload reservation blocks path');
select pg_temp.service_headers(2);
select pg_temp.denied(format('select public.app_upload_context(%L,%L)',pg_temp.uid(1),:'upload'::jsonb->>'id'),'mismatched native session rejected');
select set_config('request.headers','{}',true);
select pg_temp.denied(format('select public.app_media_access(%L,%L,%L)',pg_temp.uid(1),'ticket-attachment',:'upload'::jsonb->>'id'),'service human call missing exact session denied');
reset role;
update public.app_sessions set expires_at=now()-interval '1 second' where user_id=pg_temp.uid(1);
select pg_temp.login(1);
set local role authenticated;
select pg_temp.denied('select public.app_touch_session(true)','touch cannot revive expired');
select pg_temp.denied('select public.app_bootstrap()','expired session blocks bootstrap');
reset role;
select pg_temp.assert((select expires_at<now() from public.app_sessions where user_id=pg_temp.uid(1)),'expired stayed expired');
select count(*) as passed_assertions from test_results;
rollback;
